 return {refresh,open(){root.open=true;root.scrollIntoView({behavior:'smooth',block:'start'});},getSelected:()=>({figure:selected,joint}),cancelDrag:()=>{sphereUI?.endDrag(true);endDrag(true);},getReference:referenceSnapshot,restoreReference:restoreReferenceSnapshot,reference:referenceLayer,help,bodyLayers,sphereUI};
